import React, { useEffect, useMemo, useState } from "react";
import { fetchUsers } from "../api/userServices";
import type { User } from "../";

// ─── Constants ───────────────────────────────────────────────────────────────

const PRIMARY = "#EA580C";

const STATUS_FILTER_TABS = [
  { key: "all", label: "All" },
  { key: "active", label: "Active" },
  { key: "suspended", label: "Suspended" },
];

const PER_PAGE = 8;

// ─── Helpers ─────────────────────────────────────────────────────────────────

function initials(name: string) {
  return name
    .split(" ")
    .map((p) => p[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function formatDate(date?: string | null) {
  if (!date) return "—";

  return new Date(date).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function getStatus(user: User) {
  return user.is_active === false ? "suspended" : "active";
}

// ─── Status Badge ────────────────────────────────────────────────────────────

const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const styles: Record<string, React.CSSProperties> = {
    active: {
      background: "#DCFCE7",
      color: "#166534",
    },
    suspended: {
      background: "#FEE2E2",
      color: "#991B1B",
    },
  };

  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        padding: "4px 10px",
        borderRadius: 999,
        fontSize: 12,
        fontWeight: 600,
        ...styles[status],
      }}
    >
      <span
        style={{
          width: 6,
          height: 6,
          borderRadius: "50%",
          background: "currentColor",
        }}
      />

      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
};

// ─── Avatar ──────────────────────────────────────────────────────────────────

const UserAvatar: React.FC<{ user: User }> = ({ user }) => {
  if (user.image_url) {
    return (
      <img
        src={user.image_url}
        alt={user.name}
        style={{
          width: 38,
          height: 38,
          borderRadius: "50%",
          objectFit: "cover",
        }}
      />
    );
  }

  return (
    <div
      style={{
        width: 38,
        height: 38,
        borderRadius: "50%",
        background: "#FFEDD5",
        color: PRIMARY,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontWeight: 700,
        fontSize: 13,
      }}
    >
      {initials(user.name)}
    </div>
  );
};

// ─── Mobile User Card ────────────────────────────────────────────────────────

const MobileUserCard: React.FC<{ user: User }> = ({ user }) => {
  const status = getStatus(user);

  return (
    <div
      style={{
        background: "#fff",
        border: "1px solid #E2E8F0",
        borderRadius: 16,
        padding: 16,
        marginBottom: 12,
      }}
    >
      <div
        style={{
          display: "flex",
          gap: 12,
          alignItems: "flex-start",
        }}
      >
        <UserAvatar user={user} />

        <div style={{ flex: 1 }}>
          <div
            style={{
              fontWeight: 700,
              fontSize: 15,
              color: "#0F172A",
            }}
          >
            {user.name}
          </div>

          <div
            style={{
              fontSize: 12,
              color: "#64748B",
              marginTop: 2,
            }}
          >
            {user.phone || "No phone"}
          </div>

          <div
            style={{
              fontSize: 12,
              color: "#64748B",
              marginTop: 4,
            }}
          >
            {user.professional_headline || "No headline"}
          </div>

          <div style={{ marginTop: 10 }}>
            <StatusBadge status={status} />
          </div>
        </div>
      </div>

      <div
        style={{
          height: 1,
          background: "#F1F5F9",
          margin: "14px 0",
        }}
      />

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          fontSize: 12,
          color: "#64748B",
        }}
      >
        <span>Joined</span>
        <span>{formatDate(user.created_at)}</span>
      </div>
    </div>
  );
};

// ─── Desktop Table ───────────────────────────────────────────────────────────

const DesktopTable: React.FC<{
  users: User[];
  page: number;
  totalFiltered: number;
  onPrev: () => void;
  onNext: () => void;
  onSetPage: (p: number) => void;
}> = ({
  users,
  page,
  totalFiltered,
  onPrev,
  onNext,
  onSetPage,
}) => {
  const totalPages = Math.ceil(totalFiltered / PER_PAGE);

  const start = (page - 1) * PER_PAGE + 1;

  const end = Math.min(page * PER_PAGE, totalFiltered);

  return (
    <div
      style={{
        background: "#fff",
        borderRadius: 16,
        border: "1px solid #E2E8F0",
        overflow: "hidden",
      }}
    >
      <div style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
          }}
        >
          <thead>
            <tr style={{ background: "#F8FAFC" }}>
              {[
                "User",
                "Phone",
                "Headline",
                "Location",
                "Status",
                "Joined",
              ].map((h) => (
                <th
                  key={h}
                  style={{
                    padding: "14px 16px",
                    textAlign: "left",
                    fontSize: 12,
                    fontWeight: 700,
                    color: "#64748B",
                    borderBottom: "1px solid #E2E8F0",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>

          <tbody>
            {users.length === 0 ? (
              <tr>
                <td
                  colSpan={6}
                  style={{
                    padding: 40,
                    textAlign: "center",
                    color: "#94A3B8",
                  }}
                >
                  No users found
                </td>
              </tr>
            ) : (
              users.map((user) => {
                const status = getStatus(user);

                return (
                  <tr
                    key={user.id}
                    style={{
                      borderBottom: "1px solid #F1F5F9",
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.background = "#FAFAFA";
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.background = "white";
                    }}
                  >
                    <td style={{ padding: "14px 16px" }}>
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 12,
                        }}
                      >
                        <UserAvatar user={user} />

                        <div>
                          <div
                            style={{
                              fontWeight: 600,
                              fontSize: 14,
                              color: "#0F172A",
                            }}
                          >
                            {user.name}
                          </div>

                          <div
                            style={{
                              fontSize: 12,
                              color: "#64748B",
                              marginTop: 2,
                            }}
                          >
                            {user.user_type_names?.join(", ") || "User"}
                          </div>
                        </div>
                      </div>
                    </td>

                    <td
                      style={{
                        padding: "14px 16px",
                        fontSize: 13,
                        color: "#475569",
                      }}
                    >
                      {user.phone || "—"}
                    </td>

                    <td
                      style={{
                        padding: "14px 16px",
                        fontSize: 13,
                        color: "#475569",
                      }}
                    >
                      {user.professional_headline || "—"}
                    </td>

                    <td
                      style={{
                        padding: "14px 16px",
                        fontSize: 13,
                        color: "#475569",
                      }}
                    >
                      {user.location || "—"}
                    </td>

                    <td style={{ padding: "14px 16px" }}>
                      <StatusBadge status={status} />
                    </td>

                    <td
                      style={{
                        padding: "14px 16px",
                        fontSize: 13,
                        color: "#475569",
                      }}
                    >
                      {formatDate(user.created_at)}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}

      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "14px 16px",
          borderTop: "1px solid #E2E8F0",
        }}
      >
        <div
          style={{
            fontSize: 12,
            color: "#64748B",
          }}
        >
          Showing {totalFiltered === 0 ? 0 : start}–{end} of{" "}
          {totalFiltered}
        </div>

        <div
          style={{
            display: "flex",
            gap: 6,
          }}
        >
          <button
            onClick={onPrev}
            disabled={page === 1}
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              border: "1px solid #E2E8F0",
              background: "#fff",
              cursor: page === 1 ? "not-allowed" : "pointer",
              opacity: page === 1 ? 0.5 : 1,
            }}
          >
            ‹
          </button>

          {Array.from(
            { length: totalPages },
            (_, i) => i + 1
          ).map((p) => (
            <button
              key={p}
              onClick={() => onSetPage(p)}
              style={{
                width: 32,
                height: 32,
                borderRadius: 8,
                border:
                  p === page
                    ? "none"
                    : "1px solid #E2E8F0",
                background:
                  p === page ? PRIMARY : "#fff",
                color:
                  p === page ? "#fff" : "#475569",
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              {p}
            </button>
          ))}

          <button
            onClick={onNext}
            disabled={page === totalPages || totalPages === 0}
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              border: "1px solid #E2E8F0",
              background: "#fff",
              cursor:
                page === totalPages
                  ? "not-allowed"
                  : "pointer",
              opacity:
                page === totalPages || totalPages === 0
                  ? 0.5
                  : 1,
            }}
          >
            ›
          </button>
        </div>
      </div>
    </div>
  );
};

// ─── Main Page ───────────────────────────────────────────────────────────────

const UsersPage: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  const [search, setSearch] = useState("");
  const [activeTab, setActiveTab] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");

  const [page, setPage] = useState(1);

  // mobile

  const [isMobile, setIsMobile] = useState(
    () =>
      typeof window !== "undefined" &&
      window.innerWidth < 768
  );

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 768px)");

    setIsMobile(mq.matches);

    const handler = (e: MediaQueryListEvent) =>
      setIsMobile(e.matches);

    mq.addEventListener("change", handler);

    return () =>
      mq.removeEventListener("change", handler);
  }, []);

  // fetch users

  useEffect(() => {
    const loadUsers = async () => {
      setLoading(true);

      try {
        const data = await fetchUsers();

        setUsers(data);
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };

    loadUsers();
  }, []);

  // filtering

  const filtered = useMemo(() => {
    const q = search.toLowerCase();

    return users.filter((u) => {
      const status = getStatus(u);

      const matchesSearch =
        !q ||
        u.name?.toLowerCase().includes(q) ||
        u.phone?.toLowerCase().includes(q) ||
        u.professional_headline
          ?.toLowerCase()
          .includes(q);

      const matchesTab =
        activeTab === "all" ||
        (activeTab === "active" &&
          status === "active") ||
        (activeTab === "inactive" &&
          status === "suspended");

      const matchesStatus =
        statusFilter === "all" ||
        status === statusFilter;

      return (
        matchesSearch &&
        matchesTab &&
        matchesStatus
      );
    });
  }, [users, search, activeTab, statusFilter]);

  const paginatedUsers = filtered.slice(
    (page - 1) * PER_PAGE,
    page * PER_PAGE
  );

  const counts = useMemo(
    () => ({
      all: users.length,
      active: users.filter(
        (u) => u.is_active !== false
      ).length,
      inactive: users.filter(
        (u) => u.is_active === false
      ).length,
    }),
    [users]
  );

  if (loading) {
    return (
      <div
        style={{
          padding: 40,
          textAlign: "center",
          color: "#64748B",
        }}
      >
        Loading users...
      </div>
    );
  }

  // ─── MOBILE ──────────────────────────────────────────────────────────────

  if (isMobile) {
    return (
      <div
        style={{
          background: "#F8FAFC",
          minHeight: "100%",
        }}
      >
        {/* Header */}

        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginBottom: 18,
          }}
        >
          <h1
            style={{
              fontSize: 20,
              fontWeight: 700,
              color: "#0F172A",
            }}
          >
            Users
          </h1>

          <div
            style={{
              background: "#FFF7ED",
              color: PRIMARY,
              padding: "5px 12px",
              borderRadius: 999,
              fontSize: 12,
              fontWeight: 700,
            }}
          >
            {filtered.length}
          </div>
        </div>

        {/* Search */}

        <input
          type="text"
          placeholder="Search users..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          style={{
            width: "100%",
            padding: "12px 14px",
            borderRadius: 12,
            border: "1px solid #E2E8F0",
            background: "#fff",
            fontSize: 14,
            marginBottom: 14,
            outline: "none",
            boxSizing: "border-box",
          }}
        />

        {/* Tabs */}

        <div
          style={{
            display: "flex",
            gap: 8,
            marginBottom: 16,
            overflowX: "auto",
          }}
        >
          {STATUS_FILTER_TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => {
                setActiveTab(tab.key);
                setPage(1);
              }}
              style={{
                padding: "8px 14px",
                borderRadius: 999,
                border:
                  activeTab === tab.key
                    ? "none"
                    : "1px solid #E2E8F0",
                background:
                  activeTab === tab.key
                    ? PRIMARY
                    : "#fff",
                color:
                  activeTab === tab.key
                    ? "#fff"
                    : "#475569",
                fontSize: 12,
                fontWeight: 600,
                cursor: "pointer",
                whiteSpace: "nowrap",
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Cards */}

        {paginatedUsers.length === 0 ? (
          <div
            style={{
              padding: 40,
              textAlign: "center",
              color: "#94A3B8",
            }}
          >
            No users found
          </div>
        ) : (
          paginatedUsers.map((user) => (
            <MobileUserCard
              key={user.id}
              user={user}
            />
          ))
        )}
      </div>
    );
  }

  // ─── DESKTOP ─────────────────────────────────────────────────────────────

  return (
    <div>
      {/* Stats */}

      <div
        style={{
          display: "grid",
          gridTemplateColumns:
            "repeat(auto-fit,minmax(180px,1fr))",
          gap: 14,
          marginBottom: 20,
        }}
      >
        {[
          {
            label: "Total Users",
            value: counts.all,
          },
          {
            label: "Active Users",
            value: counts.active,
          },
          {
            label: "Inactive Users",
            value: counts.inactive,
          },
        ].map((item) => (
          <div
            key={item.label}
            style={{
              background: "#fff",
              border: "1px solid #E2E8F0",
              borderRadius: 16,
              padding: 18,
            }}
          >
            <div
              style={{
                fontSize: 12,
                color: "#64748B",
                marginBottom: 8,
              }}
            >
              {item.label}
            </div>

            <div
              style={{
                fontSize: 28,
                fontWeight: 700,
                color: "#0F172A",
              }}
            >
              {item.value}
            </div>
          </div>
        ))}
      </div>

      {/* Toolbar */}

      <div
        style={{
          background: "#fff",
          border: "1px solid #E2E8F0",
          borderRadius: 16,
          padding: 16,
          marginBottom: 18,
          display: "flex",
          gap: 12,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <input
          type="text"
          placeholder="Search users..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          style={{
            flex: 1,
            minWidth: 240,
            padding: "11px 14px",
            borderRadius: 12,
            border: "1px solid #E2E8F0",
            background: "#F8FAFC",
            outline: "none",
          }}
        />

        <select
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value);
            setPage(1);
          }}
          style={{
            padding: "11px 14px",
            borderRadius: 12,
            border: "1px solid #E2E8F0",
            background: "#F8FAFC",
            outline: "none",
          }}
        >
          <option value="all">
            All statuses
          </option>

          <option value="active">
            Active
          </option>

          <option value="suspended">
            Suspended
          </option>
        </select>
      </div>

      {/* Table */}

      <DesktopTable
        users={paginatedUsers}
        page={page}
        totalFiltered={filtered.length}
        onPrev={() =>
          setPage((p) => Math.max(1, p - 1))
        }
        onNext={() =>
          setPage((p) =>
            Math.min(
              p + 1,
              Math.ceil(filtered.length / PER_PAGE)
            )
          )
        }
        onSetPage={setPage}
      />
    </div>
  );
};

export default UsersPage;
